import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './InventoryManager.css';

const InventoryManager = () => {
    const [products, setProducts] = useState([]);
    const [suppliers, setSuppliers] = useState([]);
    const [showAddForm, setShowAddForm] = useState(false);
    const [editingProduct, setEditingProduct] = useState(null);
    const [formData, setFormData] = useState({
        name: '',
        sku: '',
        description: '',
        unitPrice: '',
        reorderPoint: '',
        targetStock: '',
        supplierId: ''
    });
    const [stockUpdate, setStockUpdate] = useState({});
    const [loading, setLoading] = useState(true);
    const [message, setMessage] = useState({ text: '', type: '' });

    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        try {
            const [productsRes, suppliersRes] = await Promise.all([
                axios.get('http://localhost:8080/api/stock/available'),
                axios.get('http://localhost:8080/api/suppliers')
            ]);
            setProducts(productsRes.data);
            setSuppliers(suppliersRes.data);
            setLoading(false);
        } catch (error) {
            console.error('Error fetching data:', error);
            showMessage('Error loading data', 'error');
            setLoading(false);
        }
    };

    const showMessage = (text, type) => {
        setMessage({ text, type });
        setTimeout(() => setMessage({ text: '', type: '' }), 3000);
    };

    const handleFormChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        const productData = {
            name: formData.name,
            sku: formData.sku,
            description: formData.description,
            unitPrice: parseFloat(formData.unitPrice) || 0,
            reorderPoint: parseInt(formData.reorderPoint) || 0,
            targetStock: parseInt(formData.targetStock) || 0,
            supplier: formData.supplierId ? { id: parseInt(formData.supplierId) } : null
        };

        if (editingProduct) {
            productData.id = editingProduct.id;
        }

        try {
            await axios.post('http://localhost:8080/api/products', productData);
            showMessage(editingProduct ? 'Product updated successfully!' : 'Product added successfully!', 'success');
            resetForm();
            fetchData();
        } catch (error) {
            console.error('Error saving product:', error);
            showMessage('Error saving product', 'error');
        }
    };

    const handleEdit = (product) => {
        setEditingProduct(product);
        setFormData({
            name: product.name || '',
            sku: product.sku || '',
            description: product.description || '',
            unitPrice: product.unitPrice || '',
            reorderPoint: product.reorderPoint || '',
            targetStock: product.targetStock || '',
            supplierId: product.supplier?.id || ''
        });
        setShowAddForm(true);
    };

    const resetForm = () => {
        setFormData({
            name: '',
            sku: '',
            description: '',
            unitPrice: '',
            reorderPoint: '',
            targetStock: '',
            supplierId: ''
        });
        setEditingProduct(null);
        setShowAddForm(false);
    };

    const handleStockChange = (productId, value) => {
        setStockUpdate({ ...stockUpdate, [productId]: value });
    };

    const updateStock = async (productId) => {
        const quantity = parseInt(stockUpdate[productId]);
        
        if (isNaN(quantity) || quantity < 0) {
            showMessage('Please enter a valid quantity', 'error');
            return;
        }

        try {
            await axios.post('http://localhost:8080/api/stock/update', {
                productId: productId,
                quantity: quantity
            });
            showMessage('Stock updated successfully!', 'success');
            setStockUpdate({ ...stockUpdate, [productId]: '' });
            fetchData();
        } catch (error) {
            console.error('Error updating stock:', error);
            showMessage('Error updating stock', 'error');
        }
    };

    if (loading) {
        return <div className="loading">Loading inventory...</div>;
    }

    return (
        <div className="inventory-manager">
            <div className="header">
                <h1>Inventory Management</h1>
                <button 
                    onClick={() => setShowAddForm(!showAddForm)}
                    className="btn-primary"
                >
                    {showAddForm ? 'Cancel' : '+ Add New Product'}
                </button>
            </div>

            {message.text && (
                <div className={`message ${message.type}`}>
                    {message.text}
                </div>
            )}

            {showAddForm && (
                <div className="form-container">
                    <h2>{editingProduct ? 'Edit Product' : 'Add New Product'}</h2>
                    <form onSubmit={handleSubmit}>
                        <div className="form-grid">
                            <div className="form-group">
                                <label>Product Name *</label>
                                <input
                                    type="text"
                                    name="name"
                                    value={formData.name}
                                    onChange={handleFormChange}
                                    required
                                />
                            </div>

                            <div className="form-group">
                                <label>SKU *</label>
                                <input
                                    type="text"
                                    name="sku"
                                    value={formData.sku}
                                    onChange={handleFormChange}
                                    required
                                />
                            </div>

                            <div className="form-group">
                                <label>Unit Price</label>
                                <input
                                    type="number"
                                    name="unitPrice"
                                    step="0.01"
                                    value={formData.unitPrice}
                                    onChange={handleFormChange}
                                />
                            </div>

                            <div className="form-group">
                                <label>Supplier</label>
                                <select
                                    name="supplierId"
                                    value={formData.supplierId}
                                    onChange={handleFormChange}
                                >
                                    <option value="">No Supplier</option>
                                    {suppliers.map(s => (
                                        <option key={s.id} value={s.id}>{s.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="form-group">
                                <label>Reorder Point</label>
                                <input
                                    type="number"
                                    name="reorderPoint"
                                    value={formData.reorderPoint}
                                    onChange={handleFormChange}
                                />
                            </div>

                            <div className="form-group">
                                <label>Target Stock</label>
                                <input
                                    type="number"
                                    name="targetStock"
                                    value={formData.targetStock}
                                    onChange={handleFormChange}
                                />
                            </div>

                            <div className="form-group full-width">
                                <label>Description</label>
                                <textarea
                                    name="description"
                                    value={formData.description}
                                    onChange={handleFormChange}
                                    rows="3"
                                />
                            </div>
                        </div>

                        <div className="form-actions">
                            <button type="submit" className="btn-primary">
                                {editingProduct ? 'Update Product' : 'Add Product'}
                            </button>
                            <button type="button" onClick={resetForm} className="btn-secondary">
                                Cancel
                            </button>
                        </div>
                    </form>
                </div>
            )}

            <div className="inventory-table-container">
                <h2>Current Inventory</h2>
                <table className="inventory-table">
                    <thead>
                        <tr>
                            <th>SKU</th>
                            <th>Product Name</th>
                            <th>Description</th>
                            <th>Unit Price</th>
                            <th>Current Stock</th>
                            <th>Update Stock</th>
                            <th>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {products.length === 0 ? (
                            <tr>
                                <td colSpan="7" className="no-data">No products found</td>
                            </tr>
                        ) : (
                            products.map(product => (
                                <tr key={product.id}>
                                    <td>{product.sku}</td>
                                    <td className="product-name">{product.name}</td>
                                    <td className="description">{product.description}</td>
                                    <td className="price">${product.unitPrice?.toFixed(2)}</td>
                                    <td>
                                        <span className={`stock-badge ${
                                            product.stockQuantity === 0 ? 'out-of-stock' : 
                                            product.stockQuantity < 10 ? 'low-stock' : 'in-stock'
                                        }`}>
                                            {product.stockQuantity}
                                        </span>
                                    </td>
                                    <td className="stock-update">
                                        <input
                                            type="number"
                                            min="0"
                                            placeholder="New qty"
                                            value={stockUpdate[product.id] || ''}
                                            onChange={(e) => handleStockChange(product.id, e.target.value)}
                                            className="stock-input"
                                        />
                                        <button 
                                            onClick={() => updateStock(product.id)}
                                            className="btn-update"
                                            disabled={!stockUpdate[product.id]}
                                        >
                                            Update
                                        </button>
                                    </td>
                                    <td>
                                        <button 
                                            onClick={() => handleEdit(product)}
                                            className="btn-edit"
                                        >
                                            Edit
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            <div className="summary-cards">
                <div className="summary-card">
                    <h3>Total Products</h3>
                    <p className="summary-value">{products.length}</p>
                </div>
                <div className="summary-card">
                    <h3>Out of Stock</h3>
                    <p className="summary-value red">
                        {products.filter(p => p.stockQuantity === 0).length}
                    </p>
                </div>
                <div className="summary-card">
                    <h3>Low Stock</h3>
                    <p className="summary-value yellow">
                        {products.filter(p => p.stockQuantity > 0 && p.stockQuantity < 10).length}
                    </p>
                </div>
                <div className="summary-card">
                    <h3>Total Stock Value</h3>
                    <p className="summary-value">
                        ${products.reduce((sum, p) => sum + (p.unitPrice * p.stockQuantity), 0).toFixed(2)}
                    </p>
                </div>
            </div>
        </div>
    );
};

export default InventoryManager;
